// test_mavlink.cpp — host tests for the MAVLink 2.0 telemetry module (I1).
//
// The encoder is byte-compared against frames generated by the official
// pymavlink toolchain (mavgen, common dialect, v2.0), captured once and
// pinned here as golden vectors:
//
//   HB_0/HB_42  HEARTBEAT        seq byte position + CRC over seq
//   ATT_7       ATTITUDE         floats incl. values that need rounding
//   GPI_3       GLOBAL_POSITION_INT  signed lat/lon, cm/s velocities
//   VFR_11      VFR_HUD          exercises MAVLink2 zero-truncation
//                                (throttle=65 => last byte 0x00 dropped)
//   GPS_5       GPS_RAW_INT      64-bit time, u16 fields, fix + sats last
//   SYS_9       SYS_STATUS       1-byte battery_remaining sorts last
//   SRV_13      SERVO_OUTPUT_RAW u8 port sorts after the u16 servos
//   TXT_2       STATUSTEXT       fixed 50-char text, id/chunk trimmed
//   RDS_0       REQUEST_DATA_STREAM (inbound) — rate first (u16 size order)
//
// Also covered: the RX state machine (magic hunt, CRC gate, signing drop,
// resync after junk) and the per-message stream scheduler.
//
// Checklist ref: I1, J2.
#include "mavlink.h"
#include "settings.h"

#include <cstdio>
#include <cstring>
#include <cstdint>

static int g_pass = 0, g_fail = 0;
static void ck(bool ok, const char* name) {
    if (ok) { g_pass++; printf("  ok   %s\n", name); }
    else    { g_fail++; printf("  FAIL %s\n", name); }
}

