// Encode helper: pack + frame into `fr`, returns frame length.
static size_t enc(uint8_t seq, uint8_t msgid, uint8_t crc_extra,
                  const uint8_t* pl, uint8_t plen, uint8_t* fr, size_t cap) {
    return mavlink_encode(seq, 1, 1, msgid, pl, plen, crc_extra, fr, cap);
}

// ===========================================================================
static void test_crc16() {
    printf("[mavlink crc16]\n");
    ck(mav_crc16_buf((const uint8_t*)"123456789", 9) == 0x6F91,
       "CRC-16/MCRF4XX check value '123456789' = 0x6F91");

    // Running accumulator must equal the one-shot helper.
    uint16_t run = 0xFFFF;
    const uint8_t msg[] = {0x09, 0x00, 0x00, 0x00, 0x01};
    for (size_t i = 0; i < sizeof(msg); i++) run = mav_crc16(run, msg[i]);
    ck(run == mav_crc16_buf(msg, sizeof(msg)), "running == one-shot");
}

// ===========================================================================
static void test_golden_frames() {
    printf("[mavlink golden frames]\n");
    uint8_t pl[MAV_PAYLOAD_MAX];
    uint8_t fr[MAV_FRAME_MAX];
    size_t n;
    uint8_t len;

    len = mav_pack_heartbeat(pl, 1, 0, 128, 0, 4);
    n = enc(0, MAV_MSG_HEARTBEAT, MAV_CRC_HEARTBEAT, pl, len, fr, sizeof(fr));
    ck(n == sizeof(G_HB_0) && memcmp(fr, G_HB_0, n) == 0,
       "HEARTBEAT seq0 byte-exact vs pymavlink");

    n = enc(42, MAV_MSG_HEARTBEAT, MAV_CRC_HEARTBEAT, pl, len, fr, sizeof(fr));
    ck(n == sizeof(G_HB_42) && memcmp(fr, G_HB_42, n) == 0,
       "HEARTBEAT seq42 (seq byte + CRC follow)");

    len = mav_pack_attitude(pl, 123456, 0.5f, -0.25f, 3.0f,
                            0.1f, -0.05f, 0.02f);
    n = enc(7, MAV_MSG_ATTITUDE, MAV_CRC_ATTITUDE, pl, len, fr, sizeof(fr));
    ck(n == sizeof(G_ATT_7) && memcmp(fr, G_ATT_7, n) == 0,
       "ATTITUDE seq7 byte-exact (float rounding matches)");

    len = mav_pack_global_position_int(pl, 999999, 404167854, -370383854,
                                       123456, 45000, 150, -200, 50, 18340);
    n = enc(3, MAV_MSG_GLOBAL_POSITION_INT, MAV_CRC_GLOBAL_POSITION_INT,
            pl, len, fr, sizeof(fr));
    ck(n == sizeof(G_GPI_3) && memcmp(fr, G_GPI_3, n) == 0,
       "GLOBAL_POSITION_INT seq7 byte-exact (signed lat/lon)");

    len = mav_pack_vfr_hud(pl, 14.5f, 15.25f, 271, 65, 123.5f, -1.25f);
    n = enc(11, MAV_MSG_VFR_HUD, MAV_CRC_VFR_HUD, pl, len, fr, sizeof(fr));
    ck(n == sizeof(G_VFR_11) && memcmp(fr, G_VFR_11, n) == 0,
       "VFR_HUD seq11 byte-exact (zero-truncation of throttle high byte)");

    len = mav_pack_gps_raw_int(pl, 1700000000000000ull, 3,
                               404167854, -370383854, 123456,
                               120, 180, 1520, 27100, 11);
    n = enc(5, MAV_MSG_GPS_RAW_INT, MAV_CRC_GPS_RAW_INT, pl, len, fr, sizeof(fr));
    ck(n == sizeof(G_GPS_5) && memcmp(fr, G_GPS_5, n) == 0,
       "GPS_RAW_INT seq5 byte-exact (64-bit time)");

    len = mav_pack_sys_status(pl, 0x00007FFF, 0x00007FFF, 0x00007FFF,
                              350, 12600, 155, 78);
    n = enc(9, MAV_MSG_SYS_STATUS, MAV_CRC_SYS_STATUS, pl, len, fr, sizeof(fr));
    ck(n == sizeof(G_SYS_9) && memcmp(fr, G_SYS_9, n) == 0,
       "SYS_STATUS seq9 byte-exact (i8 battery field last)");

    len = mav_pack_servo_output_raw(pl, 5000000, 3, 1520, 1480, 1100, 1500,
                                    0, 0, 0, 0);
    n = enc(13, MAV_MSG_SERVO_OUTPUT_RAW, MAV_CRC_SERVO_OUTPUT_RAW,
            pl, len, fr, sizeof(fr));
    ck(n == sizeof(G_SRV_13) && memcmp(fr, G_SRV_13, n) == 0,
       "SERVO_OUTPUT_RAW seq13 byte-exact (u8 port after u16s)");

    len = mav_pack_statustext(pl, 6, "wing ready");
    ck(len == 55, "STATUSTEXT payload is severity + 50 text + id + chunk");
    n = enc(2, MAV_MSG_STATUSTEXT, MAV_CRC_STATUSTEXT, pl, len, fr, sizeof(fr));
    ck(n == sizeof(G_TXT_2) && memcmp(fr, G_TXT_2, n) == 0,
       "STATUSTEXT seq2 byte-exact (id/chunk trimmed)");
}

// ===========================================================================
static void test_encode_guards() {
    printf("[mavlink encode guards]\n");
    uint8_t pl[MAV_PAYLOAD_MAX] = {0};
    uint8_t fr[MAV_FRAME_MAX];
    size_t n;

    // Undersized output buffer: refuse. Payload bytes must be nonzero or the
    // v2 zero-truncation would shrink the frame into the small buffer.
    memset(pl, 0xAA, 9);
    n = mavlink_encode(0, 1, 1, MAV_MSG_HEARTBEAT, pl, 9,
                       MAV_CRC_HEARTBEAT, fr, 20);
    ck(n == 0, "frame that does not fit returns 0");
    memset(pl, 0, sizeof(pl));

    // An all-zero payload trims to nothing: 10-byte header + 0 + 2 CRC.
    n = mavlink_encode(0, 1, 1, 42, pl, 20, 0x11, fr, sizeof(fr));
    ck(n == 12 && fr[1] == 0, "zero payload trims to 12-byte frame");

    // Null payload with zero length is legal (nothing to copy).
    n = mavlink_encode(0, 1, 1, 42, nullptr, 0, 0x11, fr, sizeof(fr));
    ck(n == 12, "null payload accepted when plen == 0");
    n = mavlink_encode(0, 1, 1, 42, nullptr, 5, 0x11, fr, sizeof(fr));
    ck(n == 0, "null payload rejected when plen > 0");
}

// ===========================================================================
static void feed(MavlinkRx& rx, const uint8_t* bytes, size_t n,
                 MavlinkRxMsg& out, int* hits) {
    for (size_t i = 0; i < n; i++)
        if (mavlink_rx_feed(&rx, bytes[i], &out)) (*hits)++;
}

static void test_rx() {
    printf("[mavlink rx]\n");
    MavlinkRx rx;
    MavlinkRxMsg m;
    int hits = 0;

    // 1. The pinned golden RDS frame parses and carries the right fields.
    mavlink_rx_init(&rx);
    feed(rx, G_RDS_0, sizeof(G_RDS_0), m, &hits);
    ck(hits == 1, "REQUEST_DATA_STREAM golden frame accepted");
    ck(m.msgid == MAV_MSG_REQUEST_DATA_STREAM, "msgid 66");
    ck(m.sysid == 1 && m.compid == 1, "source sysid/compid 1/1");
    ck(m.len == 6 && m.payload[0] == 5 && m.payload[1] == 0 &&
       m.payload[2] == 1 && m.payload[5] == 1,
       "payload = rate 5, target 1, stream 0, start 1");

    uint8_t rate = 0;
    ck(mavlink_rds_rate(&m, 1, &rate) && rate == 5, "rds_rate -> 5 for sysid 1");
    ck(!mavlink_rds_rate(&m, 2, &rate), "rds_rate ignores other sysid");

    // 2. Resync: junk before the magic must not break the next frame.
    mavlink_rx_init(&rx);
    hits = 0;
    const uint8_t junk[] = {0x11, 0x22, 0xFD, 0xAB, 0x00};
    feed(rx, junk, sizeof(junk), m, &hits);
    ck(hits == 0, "junk + stray magic produce nothing");
    feed(rx, G_RDS_0, sizeof(G_RDS_0), m, &hits);
    ck(hits == 1, "frame parses right after junk");

    // 3. A corrupted payload byte fails the CRC gate.
    mavlink_rx_init(&rx);
    hits = 0;
    uint8_t bad[sizeof(G_RDS_0)];
    memcpy(bad, G_RDS_0, sizeof(bad));
    bad[10] ^= 0x01;                  // rate low byte flips
    feed(rx, bad, sizeof(bad), m, &hits);
    ck(hits == 0, "flipped payload byte rejected by CRC");

    // 4. Signed frames (incompat bit 0) are dropped, link keeps working.
    mavlink_rx_init(&rx);
    hits = 0;
    uint8_t signed_fr[sizeof(G_RDS_0)];
    memcpy(signed_fr, G_RDS_0, sizeof(signed_fr));
    signed_fr[2] = 0x01;              // incompat_flags: signing
    feed(rx, signed_fr, sizeof(signed_fr), m, &hits);
    ck(hits == 0, "signed frame dropped (no signing support)");
    feed(rx, G_RDS_0, sizeof(G_RDS_0), m, &hits);
    ck(hits == 1, "clean frame parses after dropped signed frame");

    // 5. Unknown msgid: consumed but not reported; following frame is fine.
    mavlink_rx_init(&rx);
    hits = 0;
    uint8_t unk[16];
    uint8_t dummy = 0xAA;
    size_t un = mavlink_encode(0, 1, 1, 99, &dummy, 1, 0x55, unk, sizeof(unk));
    feed(rx, unk, un, m, &hits);
    ck(hits == 0, "unknown msgid consumed silently");
    feed(rx, G_RDS_0, sizeof(G_RDS_0), m, &hits);
    ck(hits == 1, "known frame parses after unknown frame");

    // 6. A truncated frame followed by a fresh one resynchronises.
    mavlink_rx_init(&rx);
    hits = 0;
    feed(rx, G_RDS_0, 8, m, &hits);    // header only, then wire goes away
    feed(rx, G_RDS_0, sizeof(G_RDS_0), m, &hits);
    ck(hits == 1, "restart from magic after a truncated frame");

    // 7. HEARTBEAT from the GCS is recognised (presence detection).
    mavlink_rx_init(&rx);
    hits = 0;
    feed(rx, G_HB_0, sizeof(G_HB_0), m, &hits);
    ck(hits == 1 && m.msgid == MAV_MSG_HEARTBEAT,
       "GCS HEARTBEAT accepted");

    // 8. rds_rate clamping + broadcast addressing (frames crafted with our
    //    own encoder, which the golden tests already proved byte-exact).
    uint8_t clamped = 0;
    uint8_t pl[16], fr[64], fr2[64];
    // rate 99 -> clamped to MAV_RATE_MAX; wire order: rate u16 first, then
    // target_system, target_component, req_stream_id, start_stop.
    pl[0] = 99; pl[1] = 0; pl[2] = 1; pl[3] = 0; pl[4] = 0; pl[5] = 1;
    size_t n = enc(0, MAV_MSG_REQUEST_DATA_STREAM, MAV_CRC_REQUEST_DATA_STREAM,
                   pl, 6, fr, sizeof(fr));
    MavlinkRxMsg m2;
    MavlinkRx rx2;
    mavlink_rx_init(&rx2);
    int h2 = 0;
    feed(rx2, fr, n, m2, &h2);
    ck(h2 == 1 && mavlink_rds_rate(&m2, 1, &clamped) && clamped == 25,
       "rate 99 clamps to 25");

    // rate 0 -> clamped up to MAV_RATE_MIN
    pl[0] = 0; pl[1] = 0; pl[2] = 1; pl[3] = 0; pl[4] = 0; pl[5] = 1;
    n = enc(1, MAV_MSG_REQUEST_DATA_STREAM, MAV_CRC_REQUEST_DATA_STREAM,
            pl, 6, fr2, sizeof(fr2));
    mavlink_rx_init(&rx2);
    h2 = 0;
    feed(rx2, fr2, n, m2, &h2);
    ck(h2 == 1 && mavlink_rds_rate(&m2, 1, &clamped) && clamped == 1,
       "rate 0 clamps to 1");

    // target 0 (broadcast) applies
    pl[0] = 10; pl[1] = 0; pl[2] = 0; pl[3] = 0; pl[4] = 0; pl[5] = 1;
    n = enc(2, MAV_MSG_REQUEST_DATA_STREAM, MAV_CRC_REQUEST_DATA_STREAM,
            pl, 6, fr, sizeof(fr));
    mavlink_rx_init(&rx2);
    h2 = 0;
    feed(rx2, fr, n, m2, &h2);
    ck(h2 == 1 && mavlink_rds_rate(&m2, 3, &clamped) && clamped == 10,
       "target 0 broadcast applies for any sysid");

    // start_stop = 0 -> ignore (we keep streaming). Its payload ends in a
    // zero byte, so the encoder trims it: 5-byte frame, decoder zero-pads.
    pl[0] = 10; pl[1] = 0; pl[2] = 1; pl[3] = 0; pl[4] = 0; pl[5] = 0;
    n = enc(3, MAV_MSG_REQUEST_DATA_STREAM, MAV_CRC_REQUEST_DATA_STREAM,
            pl, 6, fr, sizeof(fr));
    mavlink_rx_init(&rx2);
    h2 = 0;
    feed(rx2, fr, n, m2, &h2);
    ck(h2 == 1 && !mavlink_rds_rate(&m2, 1, &clamped),
       "start_stop=0 is ignored");
}

// ===========================================================================
#define FASTMASK (MAV_DUE_ATTITUDE | MAV_DUE_POSITION | MAV_DUE_SERVO | \
                  MAV_DUE_VFR)

static void test_schedule() {
    printf("[mavlink schedule]\n");
    MavlinkSchedule s;

    mav_schedule_init(&s, 25);
    ck(s.rate_hz == 25, "init stores the rate");
    ck(mav_schedule_due(&s, 0) == 0x7F, "first tick fires all 7 messages");
    ck(mav_schedule_due(&s, 0) == 0, "same tick fires nothing again");
    ck(mav_schedule_due(&s, 39) == 0, "39 ms: fast interval not elapsed yet");
    ck(mav_schedule_due(&s, 40) == FASTMASK, "40 ms: fast messages due (25 Hz)");
    ck(mav_schedule_due(&s, 79) == 0, "79 ms: nothing");
    ck(mav_schedule_due(&s, 80) == FASTMASK, "80 ms: fast messages due");
    ck(mav_schedule_due(&s, 1000) == 0x7F, "1000 ms: 1 Hz group fires too");

    mav_schedule_init(&s, 1);
    ck(s.rate_hz == 1, "rate 1 accepted");
    ck(mav_schedule_due(&s, 0) == 0x7F, "first tick fires all");
    ck(mav_schedule_due(&s, 999) == 0, "rate 1: nothing at 999 ms");
    ck(mav_schedule_due(&s, 1000) == 0x7F, "rate 1: all at 1000 ms");

    mav_schedule_init(&s, 0);
    ck(s.rate_hz == MAV_RATE_MIN, "rate 0 clamps to MAV_RATE_MIN");
    mav_schedule_init(&s, 90);
    ck(s.rate_hz == MAV_RATE_MAX, "rate 90 clamps to MAV_RATE_MAX");
    mav_schedule_init(&s, 25);
    mav_schedule_set_rate(&s, 5);
    ck(s.rate_hz == 5, "set_rate applies");
    ck(mav_schedule_due(&s, 0) == 0x7F, "after set_rate first tick still fires all");
    ck(mav_schedule_due(&s, 199) == 0, "rate 5: nothing at 199 ms");
    ck(mav_schedule_due(&s, 200) == FASTMASK, "rate 5: fast at 200 ms");
}

// ===========================================================================
int main() {
    printf("=== esp32-airplane MAVLink tests ===\n");
    test_crc16();
    test_golden_frames();
    test_encode_guards();
    test_rx();
    test_schedule();
    printf("\n%d passed, %d failed\n", g_pass, g_fail);
    return g_fail ? 1 : 0;
}
